// Üretilen dosya: tool/ozgun/uret.py. Matematik · Polinomlar ve çarpanlara ayırma (orta).
const ozMathematics8Orta = <(String, String, List<String>, String)>[
  ('P(x, y) = 3x²y³ − 5x⁴y + 2xy iki değişkenli polinomunun derecesi kaçtır?', '5', ['4', '6', '10'], 'Çok değişkenli polinomda bir terimin derecesi üslerin toplamıdır: x²y³ için 5, x⁴y için 5, xy için 2. Polinomun derecesi en büyük terim derecesi olan 5\'tir.'),
  ('P(x, y) = x³y² + 4x⁵ − 2y⁴ polinomunun yalnız y değişkenine göre derecesi kaçtır?', '4', ['2', '5', '10'], 'Yalnız y\'ye göre derece bakılırken x sabit gibi düşünülür; y\'nin en büyük üssü −2y⁴ terimindeki 4\'tür.'),
  ('P(x) dördüncü, Q(x) üçüncü dereceden iki polinomdur. P(Q(x)) bileşke polinomunun derecesi kaçtır?', '12', ['7', '16', '144'], 'Bileşkede dereceler çarpılır: Q\'nun en yüksek terimi x³ olduğundan P\'nin x⁴ terimi (x³)⁴ = x¹² verir. Derece 4·3 = 12\'dir.'),
  ('P(x) ve Q(x) beşinci dereceden iki polinomdur. P(x) + Q(x) toplamının derecesi için hangisi kesinlikle doğrudur?', 'En çok 5\'tir', ['Tam olarak 5\'tir', 'Tam olarak 10\'dur', 'En az 5\'tir'], 'Toplamda derece artamaz; ancak baş katsayılar birbirinin ters işaretlisi ise x⁵ terimleri yok olur ve derece düşer. Bu yüzden yalnız \'en çok 5\' kesindir.'),
  ('(x² − 2x + 3)(x³ + x − 1) çarpımı açıldığında x⁴\'lü terimin katsayısı kaçtır?', '−2', ['1', '3', '−1'], 'x⁴ yalnız x²·(x²\'li terim) ve (−2x)·x³ çarpımlarından gelir. İkinci çarpanda x²\'li terim olmadığından katsayı yalnız −2\'dir.'),
  ('Dört çarpanlı (x + 1)(x + 2)(x + 3)(x + 4) ifadesinin açılımında x\'in üçüncü kuvvetini içeren terimin katsayısını bulunuz.', '10', ['24', '35', '100'], 'Dört çarpanın üçünden x, birinden sabit seçildiğinde x³ oluşur; katsayı sabitlerin toplamı 1 + 2 + 3 + 4 = 10\'dur.'),
  ('Baş katsayısı pozitif olan bir P(x) polinomu her x için P(x)·P(x) = x⁴ − 2x² + 1 eşitliğini sağlıyor. P(3) kaçtır?', '8', ['10', '−8', '9'], 'x⁴ − 2x² + 1 = (x² − 1)² olduğundan P(x) = ±(x² − 1); baş katsayı pozitif olduğu için P(x) = x² − 1 ve P(3) = 8\'dir.'),
  ('P(x) = x³ − x polinomunun n tam sayı olmak üzere aldığı P(n) değerleri her zaman aşağıdakilerden hangisine tam bölünür?', '6', ['4', '5', '9'], 'x³ − x = (x − 1)x(x + 1) çarpanlarına ayrılır; ardışık üç tam sayının çarpımı hem 2\'ye hem 3\'e, dolayısıyla 6\'ya bölünür.'),
  ('x³ + 2x² − 5x + 1 polinomu x² + x − 1 polinomuna bölündüğünde kalan aşağıdakilerden hangisidir?', '−5x + 2', ['−5x', '−4x + 2', '−6x + 1'], 'Uzun bölmede bölüm x + 1 bulunur. (x² + x − 1)(x + 1) = x³ + 2x² − 1 olduğundan kalan (x³ + 2x² − 5x + 1) − (x³ + 2x² − 1) = −5x + 2\'dir.'),
  ('x⁴ + x³ − 3x² + 1 polinomunun x² + 2x − 1 ile uzun bölmesi yapıldığında elde edilen bölüm hangisidir?', 'x² − x', ['x² + x', 'x² − x − 1', 'x² + 3x'], 'İlk adımda x², ikinci adımda −x yazılır: (x² + 2x − 1)(x² − x) = x⁴ + x³ − 3x² + x. Geriye kalan −x + 1\'in derecesi bölenden küçük olduğundan bölme biter; bölüm x² − x\'tir.'),
  ('2x³ + 3x² − x + 5 polinomu x² + 1 ile bölünüyor. Bölüm ve kalan sırasıyla hangileridir?', '2x + 3 ve −3x + 2', ['2x + 3 ve x + 2', '2x − 3 ve −3x + 8', '2x + 1 ve −x + 4'], '(x² + 1)(2x + 3) = 2x³ + 3x² + 2x + 3\'tür. Bölünenden çıkarılınca −3x + 2 kalır.'),
  ('P(x) polinomu x² − 3x + 2 ile kalansız bölünebiliyor. Aşağıdakilerden hangisi kesinlikle sıfıra eşittir?', 'P(1) + P(2)', ['P(0)', 'P(3)', 'P(−1) + P(−2)'], 'x² − 3x + 2 = (x − 1)(x − 2) olduğundan 1 ve 2, P\'nin kökleridir. Bu yüzden P(1) = P(2) = 0 ve toplamları sıfırdır; diğerleri hakkında bilgi yoktur.'),
  ('Uzun bölme sonunda kalan 2x + 1 bulunmuşsa bölen polinomun derecesi için hangisi kesinlikle doğrudur?', 'En az 2\'dir', ['Tam olarak 1\'dir', 'En çok 1\'dir', 'Tam olarak 3\'tür'], 'Kalanın derecesi bölenin derecesinden küçük olmalıdır. Kalan birinci dereceden olduğuna göre bölen en az ikinci dereceden olmalıdır.'),
  ('4x² − 6x + 2 polinomu sıfırdan farklı 2 sabit polinomuna bölündüğünde kalan nedir?', '0', ['2', '1', '−6x + 2'], 'Bölenin derecesi 0 olduğundan kalanın derecesi 0\'dan küçük olmalı; bu ancak kalanın sıfır polinomu olmasıyla mümkündür. Gerçekten bölüm 2x² − 3x + 1\'dir.'),
  ('P(x) = (x − 4)(x² + 3) + x² − 1 olarak veriliyor. P(x)\'in x − 4 ile bölümünden kalan kaçtır?', '15', ['x² − 1', '−1', '19'], 'x² − 1\'in derecesi bölenden küçük olmadığından kalan değildir. Kalan teoremiyle P(4) = 0 + 16 − 1 = 15 bulunur.'),
  ('x³ − 4x² + x + 6 polinomu Horner yöntemiyle x − 2\'ye bölünürken tablonun alt satırında soldan sağa hangi sayılar oluşur?', '1, −2, −3, 0', ['1, −6, 13, −20', '1, 2, 5, 16', '1, −2, 5, 16'], 'Baş katsayı 1 aşağı indirilir; sonra her adımda 2 ile çarpılıp üstteki katsayıya eklenir: −4 + 2 = −2, 1 − 4 = −3, 6 − 6 = 0. Son sayı 0 kalandır.'),
  ('Üçüncü dereceden bir polinom Horner yöntemiyle x − 1\'e bölünmüş ve alt satır 3, −1, 4, 7 olarak bulunmuştur. Bölüm ve kalan hangisidir?', 'Bölüm 3x² − x + 4, kalan 7', ['Bölüm 3x³ − x² + 4x, kalan 7', 'Bölüm 3x² − x, kalan 4x + 7', 'Bölüm −x² + 4x + 7, kalan 3'], 'Alt satırın son sayısı kalandır; öncekiler bölümün katsayılarıdır. Bölünen üçüncü dereceden olduğundan bölüm ikinci derecedendir: 3x² − x + 4.'),
  ('x³ − 3x² + 4 polinomunun çift katlı kökü hangisidir?', '2', ['−1', '−2', '1'], 'x = −1 kök olduğundan x + 1 çarpandır; bölüm x² − 4x + 4 = (x − 2)² çıkar. Yani polinom (x − 2)²(x + 1) olup 2 çift katlı köktür.'),
  ('Tam sayı katsayılı ve baş katsayısı 1 olan bir polinomun rasyonel kökleri için hangisi her zaman doğrudur?', 'Tam sayıdır ve sabit terimi böler', ['Kesirli olmak zorundadır', 'Pozitif olmak zorundadır', 'Baş katsayıyı tam böler ama sabit terimle ilgisi yoktur'], 'Rasyonel kök p/q biçimindeyse q baş katsayıyı bölmelidir. Baş katsayı 1 olunca q = ±1 olur; kök tam sayıdır ve sabit terimin bir bölenidir.'),
  ('x³ + x + 1 polinomunun rasyonel kökleri için aşağıdakilerden hangisi doğrudur?', 'Hiç rasyonel kökü yoktur', ['Tek rasyonel kökü 1\'dir', 'Tek rasyonel kökü −1\'dir', 'İki rasyonel kökü vardır'], 'Rasyonel kök adayları yalnız ±1\'dir. P(1) = 3 ve P(−1) = −1 olup ikisi de sıfır değildir; bu yüzden rasyonel kök yoktur.'),
  ('Denklemi çözmeden, x³ − 3x² + 2x − 7 = 0 eşitliğini sağlayan üç sayının karelerinin toplamını hesaplayınız.', '5', ['9', '13', '−5'], 'Kökler toplamı 3, ikişerli çarpımlar toplamı 2\'dir. Kareler toplamı (toplam)² − 2·(ikişerli çarpımlar) = 9 − 4 = 5 olur.'),
  ('Kökleri a, b, c olan x³ − 2x + 5 polinomunda köklerin çarpmaya göre terslerinin toplamı kaçtır?', '2/5', ['−2/5', '5/2', '−5/2'], '1/a + 1/b + 1/c = (ab + ac + bc)/(abc) eşitliğinde ab + ac + bc = −2 ve abc = −5\'tir. Oran (−2)/(−5) = 2/5 olur.'),
  ('Dördüncü dereceden x⁴ − 3x³ + x − 8 polinomunun (karmaşık kökler dâhil) bütün köklerinin toplamı kaçtır?', '3', ['−3', '1', '8'], 'n. dereceden polinomda kökler toplamı, xⁿ⁻¹\'in katsayısının ters işaretlisinin baş katsayıya bölümüdür: −(−3)/1 = 3.'),
  ('Rasyonel katsayılı bir polinomun köklerinden biri 2 + √3 ise aşağıdakilerden hangisi de bu polinomun köküdür?', '2 − √3', ['−2 + √3', '−2 − √3', '4 − √3'], 'Rasyonel katsayılı polinomlarda a + √b biçimindeki irrasyonel kökler eşleniğiyle birlikte gelir. Bu yüzden 2 − √3 de köktür.'),
  ('P(x) polinomunun kökleri 1, 2 ve 4\'tür. P(2x) polinomunun kökleri hangileridir?', '1/2, 1 ve 2', ['2, 4 ve 8', '3, 4 ve 6', '−1, 0 ve 2'], 'P(2x) = 0 için 2x\'in 1, 2 ya da 4 olması gerekir. Buradan x = 1/2, 1 ve 2 bulunur.'),
  ('x(a − b) + y(b − a) toplamında b − a farkı a − b cinsinden yazılırsa ifade hangi çarpıma dönüşür?', '(a − b)(x − y)', ['(a − b)(x + y)', '−(a − b)(x + y)', '(a + b)(x − y)'], 'b − a = −(a − b) yazılırsa ifade x(a − b) − y(a − b) olur. Ortak çarpan a − b alınınca (a − b)(x − y) elde edilir.'),
  ('x³ + 2x² − 4x − 8 ifadesi gruplandırılarak tamamen çarpanlarına ayrıldığında hangisi elde edilir?', '(x + 2)²(x − 2)', ['(x − 2)²(x + 2)', '(x + 2)(x² + 4)', '(x + 4)(x − 2)²'], 'x²(x + 2) − 4(x + 2) = (x + 2)(x² − 4) olur. x² − 4 = (x − 2)(x + 2) yazılınca (x + 2)²(x − 2) bulunur.'),
  ('a² − b² + a − b ifadesi hangi çarpıma eşittir?', '(a − b)(a + b + 1)', ['(a + b)(a − b + 1)', '(a − b)(a + b − 1)', '(a − b)²(a + 1)'], 'a² − b² = (a − b)(a + b) yazılıp ortak çarpan a − b alınırsa (a − b)(a + b + 1) elde edilir.'),
  ('16x⁴ − 81 ifadesi gerçek katsayılı çarpanlara olabildiğince ayrıldığında hangisi bulunur?', '(2x − 3)(2x + 3)(4x² + 9)', ['(4x² − 9)(4x² + 9)', '(2x − 3)²(2x + 3)²', '(2x − 3)(2x + 3)(4x² − 9)'], 'İki kare farkı iki kez uygulanır: (4x² − 9)(4x² + 9) ve 4x² − 9 = (2x − 3)(2x + 3). 4x² + 9 gerçek sayılarda ayrılamaz.'),
  ('Aşağıdakilerden hangisi a⁴ − b⁴ ifadesinin çarpanlarından biri değildir?', 'a² + ab + b²', ['a² + b²', 'a + b', 'a − b'], 'a⁴ − b⁴ = (a² − b²)(a² + b²) = (a − b)(a + b)(a² + b²) olur. a² + ab + b² bu ayrışımda yer almaz.'),
  ('2⁸ − 1 sayısı iki kare farkı kullanılarak çarpanlarına ayrılıyor. Bu sayının asal bölenlerinin toplamı kaçtır?', '25', ['20', '22', '255'], '2⁸ − 1 = (2⁴ − 1)(2⁴ + 1) = 15·17 = 3·5·17\'dir. Asal bölenlerin toplamı 3 + 5 + 17 = 25 olur.'),
  ('x³ − x² − x + 1 dört terimlisi tamamen çarpanlarına ayrıldığında hangisi bulunur?', '(x − 1)²(x + 1)', ['(x + 1)²(x − 1)', '(x − 1)(x² + 1)', '(x − 1)(x + 1)(x² + 1)'], 'x²(x − 1) − (x − 1) = (x − 1)(x² − 1) = (x − 1)(x − 1)(x + 1) olur.'),
  ('4x² − (x + 1)² ifadesinin çarpanlarına ayrılmış hâli aşağıdakilerden hangisidir?', '(x − 1)(3x + 1)', ['(x + 1)(3x − 1)', '(3x − 1)(x − 1)', '(x − 1)(3x + 3)'], '4x² = (2x)² olduğundan iki kare farkıyla (2x − x − 1)(2x + x + 1) = (x − 1)(3x + 1) bulunur.'),
  ('(x − 1/x)² ifadesi açıldığında x\'e bağlı olmayan terim kaçtır?', '−2', ['2', '1', '0'], '(x − 1/x)² = x² − 2·x·(1/x) + 1/x² = x² − 2 + 1/x² olur; x içermeyen terim −2\'dir.'),
  ('(2x + 1)³ ifadesinin açılımında x²\'li terimin katsayısı kaçtır?', '12', ['6', '3', '24'], '(a + b)³ = a³ + 3a²b + 3ab² + b³ özdeşliğinde x² terimi 3·(2x)²·1 = 12x² olarak gelir.'),
  ('8x³ − 1 ifadesi iki küp farkı özdeşliğiyle nasıl yazılır?', '(2x − 1)(4x² + 2x + 1)', ['(2x − 1)(4x² − 2x + 1)', '(2x − 1)(4x² + 1)', '(8x − 1)(x² + x + 1)'], '8x³ = (2x)³ olduğundan a³ − b³ = (a − b)(a² + ab + b²) özdeşliği a = 2x, b = 1 ile uygulanır.'),
  ('Toplamı 5, çarpımı 6 olan iki sayının küplerinin toplamını, sayıları bulmadan hesaplayınız.', '35', ['125', '90', '215'], 'a³ + b³ = (a + b)³ − 3ab(a + b) = 125 − 3·6·5 = 125 − 90 = 35 bulunur.'),
  ('a − b = 3 ve ab = 10 ise a³ − b³ farkı kaçtır?', '117', ['27', '63', '−117'], 'a³ − b³ = (a − b)³ + 3ab(a − b) = 27 + 3·10·3 = 117\'dir. Örneğin a = 5, b = 2 için 125 − 8 = 117 doğrular.'),
  ('a − b = 2 ve a² + b² = 20 olduğuna göre a·b çarpımı kaçtır?', '8', ['16', '9', '12'], '(a − b)² = a² + b² − 2ab eşitliğinden 4 = 20 − 2ab ve ab = 8 bulunur.'),
  ('(x + y + 1)(x + y − 1) çarpımının açılımı hangisidir?', 'x² + 2xy + y² − 1', ['x² + y² − 1', 'x² + 2xy + y² + 1', 'x² + 2xy + y² − 2y − 1'], 'x + y = t denirse çarpım (t + 1)(t − 1) = t² − 1 olur. t² = x² + 2xy + y² yazılınca sonuç bulunur.'),
  ('x³ + 3x² + 3x + 1 = 125 eşitliğini sağlayan gerçek x sayısı kaçtır?', '4', ['5', '6', '−4'], 'Sol taraf (x + 1)³\'tür. (x + 1)³ = 125 = 5³ olduğundan x + 1 = 5 ve x = 4 bulunur.'),
  ('İki değişkenli x² − 2xy − 15y² ifadesi hangi çarpıma eşittir?', '(x − 5y)(x + 3y)', ['(x + 5y)(x − 3y)', '(x − 15y)(x + y)', '(x − 5y)(x − 3y²)'], 'y\'ler katsayı gibi düşünülür: çarpımı −15, toplamı −2 olan sayılar −5 ve 3\'tür. Sonuç (x − 5y)(x + 3y) olur.'),
  ('Orta terimi 7x olan 2x² + 7x + 3 ifadesinde deneme yoluyla bulunan doğru çarpanlar hangileridir?', '(2x + 1)(x + 3)', ['(2x + 3)(x + 1)', '(2x − 1)(x − 3)', '(2x + 1)(2x + 3)'], '(2x + 1)(x + 3) açılırsa 2x² + 6x + x + 3 = 2x² + 7x + 3 olur. (2x + 3)(x + 1) ise orta terimi 5x verir.'),
  ('Baş katsayısı 3 olan 3x² − 10x + 8 üç terimlisinin doğru çarpanlara ayrılışı hangisidir?', '(3x − 4)(x − 2)', ['(3x − 2)(x − 4)', '(3x + 4)(x + 2)', '(3x − 4)(3x − 2)'], '(3x − 4)(x − 2) = 3x² − 6x − 4x + 8 = 3x² − 10x + 8\'dir. Diğer seçeneklerin orta terimleri −14x, 10x ve −11x olur.'),
  ('4x² − 4x − 15 üç terimlisinin doğru çarpanlarına ayrılışı hangisidir?', '(2x − 5)(2x + 3)', ['(2x + 5)(2x − 3)', '(4x − 5)(x + 3)', '(4x + 3)(4x − 5)'], '(2x − 5)(2x + 3) = 4x² + 6x − 10x − 15 = 4x² − 4x − 15 olur. (2x + 5)(2x − 3) ise orta terimi +4x verir.'),
  ('Aşağıdakilerden hangisi x⁴ − 13x² + 36 dördüncü derece ifadesini tam bölmez?', 'x − 4', ['x − 2', 'x + 3', 'x² − 9'], 'x² = t alınırsa t² − 13t + 36 = (t − 4)(t − 9) olur. Buradan (x − 2)(x + 2)(x − 3)(x + 3) çıkar; x − 4 bu çarpanlar arasında yoktur.'),
  ('b ≠ 0 olmak üzere a² − 5ab + 6b² = 0 ise a/b oranının alabileceği değerler hangileridir?', '2 ve 3', ['−2 ve −3', '1 ve 6', '5 ve 6'], 'İfade (a − 2b)(a − 3b) biçiminde çarpanlarına ayrılır. Çarpım sıfır olduğundan a = 2b ya da a = 3b\'dir.'),
  ('2x² − 7x + 6 ifadesi \'orta terimi bölme\' (ac) yöntemiyle çarpanlarına ayrılacaktır. −7x terimi hangi iki terime ayrılmalıdır?', '−4x ve −3x', ['−6x ve −x', '−5x ve −2x', '−12x ve 5x'], 'a·c = 2·6 = 12 olduğundan çarpımı 12, toplamı −7 olan sayılar aranır: −4 ve −3. Sonra 2x² − 4x − 3x + 6 = (x − 2)(2x − 3) elde edilir.'),
  ('Sabit terimi −1 olan 12x² − x − 1 üç terimlisinin uygun çarpanlara ayrılışı hangisidir?', '(4x + 1)(3x − 1)', ['(4x − 1)(3x + 1)', '(6x + 1)(2x − 1)', '(12x + 1)(12x − 1)'], '(4x + 1)(3x − 1) = 12x² − 4x + 3x − 1 = 12x² − x − 1\'dir. (4x − 1)(3x + 1) orta terimi +x verir.'),
  ('Alanı x² + 9x + 20 santimetrekare olan bir dikdörtgenin bir kenarı x + 4 cm\'dir. Bu dikdörtgenin çevresi kaç cm\'dir?', '4x + 18', ['2x + 9', '4x + 20', '2x + 18'], 'x² + 9x + 20 = (x + 4)(x + 5) olduğundan diğer kenar x + 5\'tir. Çevre 2(x + 4 + x + 5) = 4x + 18 olur.'),
  ('x = 102 için x² − 9x + 14 ifadesinin değeri çarpanlara ayırma yardımıyla kaç bulunur?', '9500', ['9600', '9400', '95 000'], 'x² − 9x + 14 = (x − 2)(x − 7) olduğundan değer 100·95 = 9500\'dür.'),
  ('a⁴ + 4b⁴ = (a² + 2ab + 2b²)(a² − 2ab + 2b²) özdeşliği hangi matematikçinin adıyla anılır?', 'Sophie Germain', ['Pierre de Fermat', 'Carl Friedrich Gauss', 'Leonhard Euler'], 'Bu çarpanlara ayırma özdeşliği, sayılar kuramındaki çalışmalarıyla tanınan Fransız matematikçi Sophie Germain\'in adıyla anılır.'),
  ('x⁵ − 1 = (x − 1)·Q(x) eşitliğinde Q(x) polinomu aşağıdakilerden hangisidir?', 'x⁴ + x³ + x² + x + 1', ['x⁴ − x³ + x² − x + 1', 'x⁴ + 1', 'x⁴ + x³ + x² + x'], 'xⁿ − 1 = (x − 1)(xⁿ⁻¹ + xⁿ⁻² + … + x + 1) özdeşliği n = 5 için uygulanır.'),
  ('xⁿ + 1 ifadesi hangi n doğal sayıları için x + 1 çarpanına sahiptir?', 'n tek olduğunda', ['n çift olduğunda', 'n asal olduğunda', 'Her n için'], 'x = −1 yazıldığında (−1)ⁿ + 1 ancak n tekse 0 olur. Çarpan teoremine göre x + 1 yalnız n tek iken çarpandır.'),
  ('Bir x sayısı ile çarpmaya göre tersinin toplamı 3\'tür. Bu sayının küpü ile küpünün tersinin toplamı kaçtır?', '18', ['27', '24', '9'], 'x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 27 − 9 = 18 bulunur.'),
  ('x² − 5x + 1 = 0 eşitliğini sağlayan bir x için x² + 1/x² kaçtır?', '23', ['25', '27', '21'], 'Eşitlik x\'e bölünürse x − 5 + 1/x = 0, yani x + 1/x = 5 olur. Kare alınarak x² + 1/x² = 25 − 2 = 23 bulunur.'),
  ('Toplamı √5 olan x ve 1/x sayıları için dördüncü kuvvetlerin toplamı x⁴ + 1/x⁴ kaçtır?', '7', ['23', '25', '9'], 'Önce x² + 1/x² = 5 − 2 = 3 bulunur. Bir kez daha kare alınırsa x⁴ + 1/x⁴ = 9 − 2 = 7 olur.'),
  ('Pozitif a, b, c sayıları için a² + b² + c² = 29 ve ab + bc + ca = 10 ise a + b + c toplamı kaçtır?', '7', ['9', '39', '49'], '(a + b + c)² = 29 + 2·10 = 49 olur. Sayılar pozitif olduğundan toplam pozitiftir ve 7\'dir.'),
  ('a + b + c = 0 koşulu sağlandığında a³ + b³ + c³ toplamı hangi ifadeye eşittir?', '3abc', ['0', 'abc', '(a + b + c)³'], 'a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) özdeşliğinde ilk çarpan sıfır olunca a³ + b³ + c³ = 3abc kalır.'),
  ('(x³ − 8)/(x² + 2x + 4) bölümünün sadeleştirilmiş hâli hangisidir?', 'x − 2', ['x + 2', 'x² − 4', '(x − 2)²'], 'İki küp farkıyla x³ − 8 = (x − 2)(x² + 2x + 4) olduğundan ikinci dereceden çarpan sadeleşir ve x − 2 kalır.'),
  ('a ≠ ±3 için (3a − 9)/(9 − a²) ifadesi hangisine eşittir?', '−3/(a + 3)', ['3/(a + 3)', '−3/(a − 3)', '3/(a − 3)'], 'Pay 3(a − 3), payda (3 − a)(3 + a) = −(a − 3)(a + 3)\'tür. a − 3 sadeleşince −3/(a + 3) kalır.'),
  ('(x² − 1)/(x + 1) ifadesi x − 1 olarak sadeleştiriliyor. Bu eşitlik hangi x değeri için geçerli değildir?', 'x = −1', ['x = 1', 'x = 0', 'x = −1 ve x = 1'], 'Sadeleştirmeden önce payda x + 1 olduğundan x = −1\'de ifade tanımsızdır; x − 1 ise orada −2 değerini alır. Bu yüzden eşitlik x ≠ −1 koşuluyla geçerlidir.'),
  ('x ≠ 2 olmak üzere x/(x − 2) + 2/(2 − x) toplamının değeri kaçtır?', '1', ['−1', 'x + 2', '(x + 2)/(x − 2)'], '2/(2 − x) = −2/(x − 2) yazılırsa toplam (x − 2)/(x − 2) = 1 olur.'),
  ('(x² + x)/(x − 1) · (x² − 1)/x² çarpımının en sade biçimi hangisidir?', '(x + 1)²/x', ['(x + 1)/x', 'x(x + 1)²', '(x² − 1)/x'], 'İlk kesir x(x + 1)/(x − 1), ikinci kesir (x − 1)(x + 1)/x² olur. x − 1 ve bir x sadeleşince (x + 1)²/x kalır.'),
  ('a ≠ 0 ve a ≠ −2 olmak üzere (a² − 4)/a ifadesi (a + 2)/a² ifadesine bölünürse sonuç hangisi olur?', 'a(a − 2)', ['(a − 2)/a', 'a² − 4', '(a − 2)/a³'], 'Bölme, ters ile çarpmadır: (a − 2)(a + 2)/a · a²/(a + 2) = a(a − 2).'),
  ('Merdiven kesri (1 − 1/x)/(1 − 1/x²) sadeleştirildiğinde hangi ifade bulunur?', 'x/(x + 1)', ['(x + 1)/x', 'x/(x − 1)', '1/(x + 1)'], 'Pay (x − 1)/x, payda (x − 1)(x + 1)/x² olur. Bölme yapılınca x/(x + 1) kalır.'),
  ('x ≠ 3 olmak üzere paydası 3 − x olan (x² − 6x + 9)/(3 − x) kesrinde payın tam kare olduğu fark edilirse kesir neye sadeleşir?', '3 − x', ['x − 3', 'x + 3', '−(x + 3)'], 'Pay (x − 3)², payda −(x − 3)\'tür. Sadeleşince −(x − 3) = 3 − x kalır.'),
  ('1 + 1/(1 + 1/x) iç içe kesri tek bir kesir olarak nasıl yazılır?', '(2x + 1)/(x + 1)', ['(x + 2)/(x + 1)', '(2x + 1)/x', '2x/(x + 1)'], '1 + 1/x = (x + 1)/x olduğundan 1/(1 + 1/x) = x/(x + 1) olur. Buna 1 eklenince (2x + 1)/(x + 1) bulunur.'),
  ('x² − 4 ve x² + 4x + 4 polinomlarının en küçük ortak katı (EKOK) hangisidir?', '(x − 2)(x + 2)²', ['(x − 2)(x + 2)', '(x² − 4)(x² + 4x + 4)', '(x + 2)²'], 'x² − 4 = (x − 2)(x + 2) ve x² + 4x + 4 = (x + 2)²\'dir. EKOK için her çarpan en büyük kuvvetiyle alınır: (x − 2)(x + 2)².'),
  ('x³ − x ile x² + x polinomlarının en büyük ortak böleni (EBOB) aşağıdakilerden hangisidir?', 'x(x + 1)', ['x(x − 1)', 'x + 1', 'x(x − 1)(x + 1)'], 'x³ − x = x(x − 1)(x + 1), x² + x = x(x + 1)\'dir. İkisinde ortak olan çarpanlar x ve x + 1\'dir.'),
  ('x² − 1, x² − 2x + 1 ve x³ − 1 polinomlarının üçünü birden bölen en yüksek dereceli monik ortak bölen hangisidir?', 'x − 1', ['(x − 1)²', 'x + 1', 'x² + x + 1'], 'Ayrışımlar (x − 1)(x + 1), (x − 1)² ve (x − 1)(x² + x + 1)\'dir. Üçünde ortak olan tek çarpan x − 1\'dir.'),
  ('x² − 2 polinomunun çarpanlara ayrılabilirliği için hangisi doğrudur?', 'Rasyonelde ayrılamaz, gerçekte ayrılır', ['Gerçek sayılarda da ayrılamaz', 'Rasyonel katsayılı iki çarpana ayrılır', 'Yalnız karmaşık katsayılarla ayrılır'], 'Kökleri ±√2 irrasyoneldir; bu yüzden rasyonel katsayılı birinci derece çarpanı yoktur. Gerçek sayılarda ise (x − √2)(x + √2) biçiminde ayrılır.'),
  ('Üçüncü dereceden bir polinomun ardışık tam sayılardaki değerleri yazılıp art arda farklar alınıyor. Kaçıncı farklar sabit bir sayı olur?', 'Üçüncü farklar', ['Birinci farklar', 'İkinci farklar', 'Dördüncü farklar'], 'n. dereceden bir polinomun eşit aralıklı değerlerinde n. farklar sabittir, (n + 1). farklar sıfırdır. Üçüncü derecede sabit olan üçüncü farklardır.'),
  ('Derecesi en çok n olan bir polinomun tek türlü belirlenebilmesi için en az kaç farklı noktadaki değerinin bilinmesi gerekir?', 'n + 1', ['n', '2n', 'n − 1'], 'Derecesi en çok n olan polinomda n + 1 bilinmeyen katsayı vardır. Farklı n + 1 noktadaki değerler bu katsayıları tek türlü belirler.'),
  ('Bir polinomun x − a ile bölümünü katsayılarla hızlıca yapan sentetik bölme yöntemi 1819\'da yayımladığı makale nedeniyle hangi İngiliz matematikçinin adıyla anılır?', 'William George Horner', ['Isaac Newton', 'George Boole', 'Brook Taylor'], 'Yöntem, 1819\'da Royal Society\'de yayımlanan makalesi nedeniyle William George Horner\'ın adıyla anılır; benzer bir yöntemi daha önce Paolo Ruffini de vermiştir.'),
  ('Dördüncü dereceden genel denklemin kök almalı çözümünü bulan ve sonucu Cardano\'nun Ars Magna\'sında yayımlanan, Cardano\'nun öğrencisi olan matematikçi kimdir?', 'Lodovico Ferrari', ['Niccolò Tartaglia', 'Scipione del Ferro', 'François Viète'], 'Dördüncü dereceden denklemlerin çözümü Lodovico Ferrari\'ye aittir ve 1545\'te Ars Magna\'da yayımlanmıştır.'),
  ('Kübik denklem çözüm yöntemini gizli tutması koşuluyla Cardano\'ya açıklayan, Cardano\'nun yöntemi yayımlaması üzerine onunla tartışmaya giren matematikçi kimdir?', 'Niccolò Tartaglia', ['Scipione del Ferro', 'Lodovico Ferrari', 'Évariste Galois'], 'Tartaglia yöntemini 1539\'da Cardano\'ya açıklamıştır. Cardano 1545\'te Ars Magna\'da yayımlayınca aralarında ünlü bir öncelik tartışması çıkmıştır.'),
  ('x ve y pozitif tam sayılar olmak üzere x² − y² = 15 eşitliğini sağlayan kaç farklı (x, y) ikilisi vardır?', '2', ['1', '3', '4'], '(x − y)(x + y) = 15 ve x + y > x − y > 0 olmalıdır: 1·15 ile (8, 7), 3·5 ile (4, 1) bulunur.'),
  ('P(x) = x² + x + 1 olmak üzere P(x)·P(−x) çarpımı hangi polinoma eşittir?', 'x⁴ + x² + 1', ['x⁴ − x² + 1', 'x⁴ + 2x² + 1', 'x⁴ + 1'], 'P(−x) = x² − x + 1\'dir. (x² + 1 + x)(x² + 1 − x) = (x² + 1)² − x² = x⁴ + x² + 1 bulunur.'),
  ('Birinci dereceden on çarpanın çarpımı olan (x − 1)(x − 2)⋯(x − 10) polinomunda dokuzuncu dereceden terimin katsayısını, açılım yapmadan bulunuz.', '−55', ['55', '−45', '−10'], 'Dokuz çarpandan x, birinden sabit seçildiğinde x⁹ oluşur. Katsayı sabitlerin toplamıdır: −(1 + 2 + ⋯ + 10) = −55.'),
  ('Gerçek katsayılı P(x) ve Q(x) için P(x)·Q(x) = x³ − 1\'dir. P(x) birinci dereceden ve baş katsayısı 1 ise Q(x) hangisidir?', 'x² + x + 1', ['x² − x + 1', 'x² + 1', 'x² − 1'], 'x³ − 1 = (x − 1)(x² + x + 1) ve x² + x + 1\'in gerçek kökü yoktur. Bu yüzden birinci dereceden monik çarpan yalnız x − 1 olabilir; Q(x) = x² + x + 1\'dir.'),
  ('P(x²) = x⁴ + 3x² + 2 eşitliği her x için sağlanıyorsa P(x) polinomu aşağıdakilerden hangisidir?', 'x² + 3x + 2', ['x⁴ + 3x² + 2', 'x² + 3x + 4', 'x + 3√x + 2'], 'x² = t yazılırsa P(t) = t² + 3t + 2 olur; değişkenin adı değiştirilince P(x) = x² + 3x + 2.'),
  ('Bir öğrenci 2x² − 8 ifadesini (2x − 4)(x + 2) olarak çarpanlarına ayırıyor. Bu çalışma için en doğru değerlendirme hangisidir?', 'Eşitlik doğru ama ayrışım tamamlanmamış', ['Eşitlik yanlıştır; çarpım 2x² − 16 verir', 'Ayrışım tamdır, daha fazla ayrılamaz', 'İşaret hatası vardır; x − 2 olmalıydı'], '(2x − 4)(x + 2) = 2x² − 8 doğrudur; ancak 2x − 4 = 2(x − 2) olduğundan tam ayrışım 2(x − 2)(x + 2)\'dir.'),
  ('Aşağıdaki eşitliklerden hangisi her a ve b için doğru değildir?', '(a − b)² = −(b − a)²', ['a² + b² = (a − b)² + 2ab', '(a − b)³ = −(b − a)³', 'a³ + b³ = (a + b)³ − 3ab(a + b)'], '(a − b)² ile (b − a)² eşittir; önüne eksi konan eşitlik a ≠ b iken bozulur. Diğer üçü açılımla doğrulanan özdeşliklerdir.'),
  ('Her gerçek a ve b için a² + b² ≥ 2ab eşitsizliğinin doğru olduğunu gösteren en kısa gerekçe hangisidir?', '(a − b)² ≥ 0 olması', ['(a + b)² ≥ 0 olması', 'a² ≥ 0 ve b² ≥ 0 olması', 'ab ≤ 0 olması'], 'a² + b² − 2ab = (a − b)²\'dir ve bir gerçek sayının karesi negatif olamaz. Eşitlik yalnız a = b iken sağlanır.'),
  ('n(n + 1)(n + 2)(n + 3) + 1 = (n² + 3n + 1)² özdeşliği kullanılırsa 5·6·7·8 + 1 sayısı hangi sayının karesidir?', '41', ['39', '40', '43'], 'n = 5 için n² + 3n + 1 = 25 + 15 + 1 = 41\'dir. Gerçekten 1680 + 1 = 1681 = 41²\'dir.'),
  ('x³ − 2x² − 9x + 18 polinomunun köklerinden ikisinin toplamı sıfırdır. Üçüncü kök kaçtır?', '2', ['−2', '3', '9'], 'Üç kökün toplamı 2\'dir. İki kökün toplamı 0 olduğundan üçüncü kök 2\'dir; gerçekten polinom (x − 2)(x² − 9)\'dur.'),
  ('(x² + ax + 1)(x − 2) çarpımında x²\'li terim bulunmuyorsa a kaçtır?', '2', ['−2', '1', '1/2'], 'Çarpımda x² terimi a·x·x ve x²·(−2) çarpımlarından gelir: (a − 2)x². Bu terimin olmaması için a = 2 olmalıdır.'),
  ('(3x + 2y)(3x − 2y)(9x² + 4y²) çarpımının sonucu hangisidir?', '81x⁴ − 16y⁴', ['81x⁴ + 16y⁴', '9x⁴ − 4y⁴', '(9x² − 4y²)²'], 'İlk iki çarpan 9x² − 4y² verir. Bu da 9x² + 4y² ile çarpılınca yeniden iki kare farkı oluşur: 81x⁴ − 16y⁴.'),
  ('(x − 1)(x + 1)(x² + 1)(x⁴ + 1) çarpımı hangi ifadeye eşittir?', 'x⁸ − 1', ['x⁸ + 1', 'x⁷ − 1', 'x⁶ − 1'], 'Soldan başlayarak iki kare farkı art arda uygulanır: (x² − 1)(x² + 1) = x⁴ − 1, (x⁴ − 1)(x⁴ + 1) = x⁸ − 1.'),
  ('x² + xy = 12 ve y² + xy = 4 eşitlikleri veriliyor. x + y pozitif olduğuna göre x + y kaçtır?', '4', ['16', '2', '8'], 'İki eşitlik toplanırsa x² + 2xy + y² = 16, yani (x + y)² = 16 olur. Pozitif değer 4\'tür.'),
  ('Birbirinin eşleniği olan 2 + √3 ve 2 − √3 sayılarının karelerinin toplamı kaçtır?', '14', ['16', '7', '12'], 'a + b = 4 ve ab = 4 − 3 = 1\'dir. a² + b² = (a + b)² − 2ab = 16 − 2 = 14.'),
  ('a + b = 4 ve ab = 3 ise a³b + ab³ ifadesinin değeri kaçtır?', '30', ['48', '36', '10'], 'a³b + ab³ = ab(a² + b²) ve a² + b² = 16 − 6 = 10\'dur. Değer 3·10 = 30 olur.'),
  ('Dört terimli x³ − 3x² − 4x + 12 ifadesi gruplama yapılarak tamamen ayrıldığında hangi üç çarpan elde edilir?', '(x − 3)(x − 2)(x + 2)', ['(x + 3)(x − 2)(x + 2)', '(x − 3)(x − 4)(x + 1)', '(x − 3)(x² − 4x + 4)'], 'x²(x − 3) − 4(x − 3) = (x − 3)(x² − 4) = (x − 3)(x − 2)(x + 2) olur.'),
  ('Kökleri toplamı sıfır olan x³ − 7x + 6 polinomunun çarpanlarına ayrılmış biçimi hangisidir?', '(x − 1)(x − 2)(x + 3)', ['(x + 1)(x + 2)(x − 3)', '(x − 1)(x + 2)(x − 3)', '(x − 1)(x + 2)(x − 3)(x + 1)'], 'x = 1 kök olduğundan bölüm x² + x − 6 = (x + 3)(x − 2) bulunur. Sonuç (x − 1)(x − 2)(x + 3)\'tür.'),
  ('Karesi alınmış x² + 1 ile 4x² arasındaki fark, iki kare farkı özdeşliğiyle hangi biçime getirilir?', '(x − 1)²(x + 1)²', ['(x² − 1)(x² + 3)', '(x − 1)⁴', '(x² + 2x − 1)(x² − 2x − 1)'], 'İki kare farkıyla (x² + 1 − 2x)(x² + 1 + 2x) = (x − 1)²(x + 1)² bulunur.'),
  ('x(x − 1) − y(y − 1) farkı açılıp x − y parantezine alınırsa hangi sonuç elde edilir?', '(x − y)(x + y − 1)', ['(x − y)(x + y + 1)', '(x + y)(x − y − 1)', '(x − y)(x + y)(x + y − 1)'], 'Açılınca x² − y² − (x − y) olur. x − y ortak çarpanı alınırsa (x − y)(x + y − 1) bulunur.'),
  ('(a − b)² − (b − a) ifadesinin çarpanlara ayrılmış biçimi hangisidir?', '(a − b)(a − b + 1)', ['(a − b)(a − b − 1)', '(b − a)(a − b + 1)', '(a − b)²(a − b + 1)'], '−(b − a) = +(a − b) olduğundan ifade (a − b)² + (a − b) = (a − b)(a − b + 1) olur.'),
  ('Hacmi x³ + 7x² + 14x + 8 cm³ olan bir dikdörtgenler prizmasının ayrıtları x\'in baş katsayısı 1 olan birinci dereceden ifadeleridir. En uzun ayrıt hangisidir?', 'x + 4', ['x + 8', 'x + 2', '2x + 4'], 'x = −1 kök olduğundan bölüm x² + 6x + 8 = (x + 2)(x + 4) olur. Ayrıtlar x + 1, x + 2 ve x + 4\'tür; en uzunu x + 4.'),
  ('P(x) = x² olmak üzere P(x + h) − P(x) farkı hangi ifadeye eşittir?', '2xh + h²', ['h²', '2x + h', 'x² + 2xh + h²'], 'P(x + h) = x² + 2xh + h²\'dir; P(x) çıkarılınca 2xh + h² kalır.'),
  ('Aşağıdaki gerçek fonksiyonlardan hangisi bir polinom fonksiyonu değildir?', 'f(x) = |x|', ['f(x) = 0', 'f(x) = (x − 1)²', 'f(x) = x/4 − 2'], 'Mutlak değer fonksiyonu x < 0 ve x ≥ 0 için iki ayrı kuralla tanımlanır ve tek bir polinom ifadesiyle yazılamaz. Diğerleri katsayıları gerçek, üsleri doğal sayı olan polinomlardır.'),
  ('x⁴ − 2x³ + 3x − 4 polinomu Horner yöntemiyle x + 1\'e bölündüğünde elde edilen bölüm hangisidir?', 'x³ − 3x² + 3x', ['x³ − x² − x + 4', 'x³ − 3x² + 3x − 4', 'x³ − 2x² + 3'], 'Çarpan −1 ile tablo: 1; −2 − 1 = −3; 0 + 3 = 3; 3 − 3 = 0; −4 − 0 = −4. Bölüm x³ − 3x² + 3x + 0, kalan −4\'tür.'),
  ('3x³ − 2x² + 5x − 1 polinomunun Horner yöntemine uygun iç içe yazılışı hangisidir?', '((3x − 2)x + 5)x − 1', ['(3x − 2)(x + 5)x − 1', '3x(x − 2)(x + 5) − 1', '((3x² − 2)x + 5)x − 1'], '((3x − 2)x + 5)x − 1 açılırsa (3x² − 2x + 5)x − 1 = 3x³ − 2x² + 5x − 1 elde edilir.'),
  ('p ve q gerçek sayılar olmak üzere x³ + px + q polinomunun köklerinin toplamı kaçtır?', '0', ['−p', 'q', '−q'], 'Kökler toplamı x²\'nin katsayısının ters işaretlisinin baş katsayıya oranıdır. x² terimi olmadığından bu toplam 0\'dır.'),
  ('Ardışık iki tek sayının karelerinin farkı için aşağıdakilerden hangisi her zaman doğrudur?', '8\'in katıdır', ['Tek sayıdır', 'Tam karedir', '12\'nin katıdır'], '(2n + 1)² − (2n − 1)² = [(2n + 1) − (2n − 1)]·[(2n + 1) + (2n − 1)] = 2·4n = 8n\'dir.'),
  ('Ardışık dört tam sayı küçükten büyüğe a, b, c, d ise a·d − b·c değeri her zaman kaçtır?', '−2', ['2', '0', '−1'], 'a = n alınırsa n(n + 3) − (n + 1)(n + 2) = n² + 3n − (n² + 3n + 2) = −2 bulunur.'),
  ('Birler basamağı 5 olan sayıların karesini kısa yoldan hesaplama (ör. 65² = 6·7 yüz + 25) hangi özdeşliğe dayanır?', '(10a + 5)² = 100a(a + 1) + 25', ['(10a + 5)² = 100a² + 25', '(10a + 5)² = 10a(a + 5) + 25', '(10a + 5)² = 100a(a + 5) + 5²'], '(10a + 5)² = 100a² + 100a + 25 = 100a(a + 1) + 25\'tir. Örneğin a = 6 için 4200 + 25 = 4225 = 65² bulunur.'),
  ('Tanımlı olduğu x değerleri için (x² − x − 6)/(x² − 9) · (x + 3)/(x + 2) çarpımı neye eşittir?', '1', ['x − 3', '(x + 3)/(x − 3)', '−1'], 'Birinci kesir (x − 3)(x + 2)/((x − 3)(x + 3)) = (x + 2)/(x + 3)\'tür. (x + 3)/(x + 2) ile çarpılınca 1 kalır.'),
  ('Terslerinin toplamı 1/2, kendi toplamları 10 olan x ve y sayılarının çarpımını bulunuz.', '20', ['5', '10', '−20'], '1/x + 1/y = (x + y)/(xy) olduğundan 10/(xy) = 1/2 ve xy = 20 bulunur.'),
  ('x/y = 3 olduğuna göre (x² − y²)/(x² + xy) ifadesinin değeri kaçtır?', '2/3', ['5/6', '3/4', '1/3'], '(x − y)(x + y)/(x(x + y)) = (x − y)/x = 1 − y/x = 1 − 1/3 = 2/3 bulunur.'),
  ('x ≠ −1 için (x³ + 1)/(x + 1) − x² ifadesi neye eşittir?', '1 − x', ['x − 1', '1 + x', '−x² + 1'], '(x³ + 1)/(x + 1) = x² − x + 1 olduğundan x² çıkarılınca −x + 1 kalır.'),
  ('Cebirin temel teoreminin kanıtını 1799\'da doktora tezi olarak sunan matematikçi kimdir?', 'Carl Friedrich Gauss', ['Leonhard Euler', 'Joseph-Louis Lagrange', 'Augustin-Louis Cauchy'], 'Gauss 1799 tarihli doktora tezinde her polinom denkleminin bir kökü olduğunu kanıtlamaya çalışmış; ileriki yıllarda teoreme başka kanıtlar da vermiştir.'),
  ('x⁴ + 4x² − 5 ifadesi gerçek katsayılarla olabildiğince çarpanlarına ayrıldığında hangisi elde edilir?', '(x² + 5)(x − 1)(x + 1)', ['(x² − 5)(x² + 1)', '(x² + 5)(x² + 1)', '(x² + 5)(x − 1)(x + 1)(x² + 1)'], 'x² = t ile t² + 4t − 5 = (t + 5)(t − 1) olur. x² − 1 = (x − 1)(x + 1) ayrılır; x² + 5 gerçek sayılarda ayrılamaz.'),
  ('4ˣ − 5·2ˣ + 4 ifadesi 2ˣ = t dönüşümüyle çarpanlarına ayrılırsa hangi sonuç bulunur?', '(2ˣ − 1)(2ˣ − 4)', ['(2ˣ + 1)(2ˣ + 4)', '(4ˣ − 1)(2ˣ − 4)', '(2ˣ − 1)(2ˣ − 4)(2ˣ + 1)'], '4ˣ = (2ˣ)² = t² olduğundan ifade t² − 5t + 4 = (t − 1)(t − 4) olur; t yerine 2ˣ yazılır.'),
  ('n doğal sayı olmak üzere x²ⁿ − 2xⁿ + 1 ifadesi hangi biçimde yazılabilir?', '(xⁿ − 1)²', ['(x² − 1)ⁿ', '(xⁿ + 1)²', '(xⁿ − 1)(xⁿ + 1)'], 'xⁿ = t denirse ifade t² − 2t + 1 = (t − 1)² olur.'),
  ('x > 0 olmak üzere x + 2√x − 3 ifadesi √x cinsinden hangi çarpıma ayrılır?', '(√x + 3)(√x − 1)', ['(√x − 3)(√x + 1)', '(x + 3)(x − 1)', '(√x + 3)(√x − 1)²'], '√x = t alınırsa x = t² ve ifade t² + 2t − 3 = (t + 3)(t − 1) olur.'),
  ('Çevresi 20 cm, alanı 21 cm² olan bir dikdörtgenin köşegen uzunluğunun karesi kaç cm²\'dir?', '58', ['100', '79', '42'], 'Kenarlar a ve b ise a + b = 10, ab = 21\'dir. Köşegen² = a² + b² = (a + b)² − 2ab = 100 − 42 = 58.'),
  ('Kenarı a cm olan kare bir resmin çevresine her yerde x cm genişliğinde bir çerçeve yapılıyor. Çerçevenin alanı hangi ifadeyle verilir?', '4x(a + x)', ['4ax', 'x(a + 2x)', '2x(2a + x)'], 'Dış kare alanı (a + 2x)², iç kare a²\'dir. Farkları iki kare farkıyla (2x)(2a + 2x) = 4x(a + x) olur.'),
  ('Kenarı a birim olan bir küpün kenarı 1 birim artırılırsa hacmi kaç birimküp artar?', '3a² + 3a + 1', ['3a + 1', 'a² + a + 1', 'a³ + 3a² + 3a + 1'], 'Artış (a + 1)³ − a³ = a³ + 3a² + 3a + 1 − a³ = 3a² + 3a + 1\'dir.'),
  ('İki ifadenin özdeş olup olmadığı x yerine birkaç sayı yazılarak sınanıyor. Bu yöntemle ilgili hangisi doğrudur?', 'Tek bir uyumsuz değer özdeş olmadıklarını kanıtlar', ['Bir değerde eşit çıkmaları özdeşliği kanıtlar', 'İki değerde eşitlik her zaman yeter', 'Sayı denemesi özdeşlik konusunda hiçbir bilgi vermez'], 'Bir değerde bile farklı sonuç çıkması özdeşliği çürütür. Ancak birkaç değerde eşitlik yalnız ipucudur; n. dereceden polinomlar için en az n + 1 farklı değerde eşitlik gerekir.'),
  ('Üç terimli x² − 3x + 2 kendisiyle çarpılırsa sonuçta x² içeren terimin katsayısı ne olur?', '13', ['4', '9', '−12'], 'x² terimi x²·2 çarpımından iki kez (4x²) ve (−3x)² çarpımından (9x²) gelir: 4 + 9 = 13.'),
  ('x⁴ − 3x² + 2 polinomunun kökleri arasında aşağıdakilerden hangisi bulunur?', '√2', ['2', '3', '−√3'], 'x² = t ile t² − 3t + 2 = (t − 1)(t − 2) olur. Buradan x² = 1 ya da x² = 2, yani kökler ±1 ve ±√2\'dir.'),
  ('Bir polinomun katsayıları toplamı sıfır ise aşağıdakilerden hangisi bu polinomun kesinlikle bir çarpanıdır?', 'x − 1', ['x + 1', 'x', 'x² − 1'], 'Katsayılar toplamı P(1)\'e eşittir. P(1) = 0 olduğundan çarpan teoremine göre x − 1 bir çarpandır.'),
  ('a gerçek sayısı ne olursa olsun x³ + ax² + ax + 1 polinomunun kesinlikle sahip olduğu çarpan hangisidir?', 'x + 1', ['x − 1', 'x² + 1', 'x + a'], 'x = −1 için −1 + a − a + 1 = 0 olur. Bu her a için geçerli olduğundan x + 1 daima bir çarpandır.'),
  ('(x + 2)² − (x + 1)² − (x − 1)² + (x − 2)² ifadesi sadeleştirildiğinde hangi sonuç elde edilir?', '6', ['0', '2x', '4x + 6'], '(x + 2)² + (x − 2)² = 2x² + 8 ve (x + 1)² + (x − 1)² = 2x² + 2\'dir. Farkları 6 olup x\'ten bağımsızdır.'),
  ('Hesap makinesi kullanmadan √(1 + 2023·2025) kökünü bulmak isteyen biri hangi sonuca ulaşır?', '2024', ['2023', '2025', '2024²'], '2023·2025 = (2024 − 1)(2024 + 1) = 2024² − 1\'dir. 1 eklenince 2024² olur ve karekökü 2024\'tür.'),
  ('Toplamlarının karesi 49, farklarının karesi 9 olan iki sayının çarpımını hesaplayınız.', '10', ['20', '40', '−10'], '(a + b)² − (a − b)² = 4ab olduğundan 49 − 9 = 40 = 4ab ve ab = 10 bulunur.'),
  ('x³ − 1 polinomu x − 1 polinomuna bölündüğünde elde edilen bölüm Q(x) ise Q(1) kaçtır?', '3', ['0', '1', '2'], 'x³ − 1 = (x − 1)(x² + x + 1) olduğundan bölme kalansızdır ve bölüm Q(x) = x² + x + 1\'dir. Q(1) = 1 + 1 + 1 = 3 bulunur.'),
  ('P(x) herhangi bir polinom ve a bir gerçek sayı ise P(x) − P(a) farkı için hangisi her zaman doğrudur?', 'x − a ile tam bölünür', ['x + a ile tam bölünür', 'Sabit bir polinomdur', 'P(x) ile aynı baş katsayıya sahip değildir'], 'P(x) − P(a) polinomu x = a için sıfır olur. Çarpan teoremine göre x − a bu farkın bir çarpanıdır.'),
  ('Polinomlarda bölme algoritmasına göre bölen sıfır polinomu olmadığında bölüm ve kalan için hangisi doğrudur?', 'İkisi de tek türlü belirlidir', ['Bölüm tek, kalan birden çok olabilir', 'Kalan tek, bölüm birden çok olabilir', 'Bölen ikinci dereceyse belirsizdir'], 'P = B·Q + K ve der K < der B koşulları altında Q ve K tek türlü belirlenir. Tam sayılardaki kalanlı bölmede olduğu gibi tekliğin ölçütü kalanın \'küçük\' olmasıdır.'),
  ('Aralarında 2 fark bulunan iki sayının çarpımına 1 eklenirse ne elde edileceğini gösteren (x − 1)(x − 3) + 1 ifadesi neye eşittir?', '(x − 2)²', ['(x − 1)²', 'x² − 4x', '(x − 2)² + 1'], '(x − 1)(x − 3) + 1 = x² − 4x + 3 + 1 = x² − 4x + 4 = (x − 2)²\'dir. Örneğin 9·11 + 1 = 100 = 10².'),
  ('Baş katsayısı 2 olan 2x³ + 3x² − 2x − 3 polinomu gruplandırılarak tamamen ayrılınca hangisi bulunur?', '(2x + 3)(x − 1)(x + 1)', ['(2x − 3)(x − 1)(x + 1)', '(2x + 3)(x² + 1)', '(2x + 3)(x − 1)(x + 1)²'], 'x²(2x + 3) − (2x + 3) = (2x + 3)(x² − 1) = (2x + 3)(x − 1)(x + 1).'),
  ('x + y toplamı tek bir değişken gibi düşünülürse (x + y)² − 5(x + y) + 6 nasıl ayrılır?', '(x + y − 2)(x + y − 3)', ['(x + y + 2)(x + y + 3)', '(x + y − 1)(x + y − 6)', '(x + y − 2)(x + y + 3)'], 'x + y = t denirse t² − 5t + 6 = (t − 2)(t − 3) olur ve t yerine x + y yazılır.'),
  ('Verilen n + 1 farklı noktadan geçen ve derecesi en çok n olan polinomu açık bir toplam formülüyle veren interpolasyon yöntemi hangi matematikçinin adıyla anılır?', 'Lagrange', ['Horner', 'Descartes', 'Viète'], 'Lagrange interpolasyon polinomu, her noktaya karşılık gelen temel polinomların ağırlıklı toplamıdır ve 18. yüzyılda Joseph-Louis Lagrange tarafından yayımlanmıştır.'),
  ('1/(x² + x) kesri basit kesirlere ayrıldığında hangi farka eşit olur?', '1/x − 1/(x + 1)', ['1/x + 1/(x + 1)', '1/(x + 1) − 1/x', '1/x − 1/(x + 1) + 1/x²'], 'x² + x = x(x + 1)\'dir ve 1/x − 1/(x + 1) = (x + 1 − x)/(x(x + 1)) = 1/(x² + x) olur.'),
  ('2x/(x² − 1) − 1/(x − 1) farkının en sade biçimi aşağıdakilerden hangisidir?', '1/(x + 1)', ['1/(x − 1)', '(x + 1)/(x² − 1)', 'x/(x + 1)'], 'Ortak payda x² − 1 ile pay 2x − (x + 1) = x − 1 olur. (x − 1)/((x − 1)(x + 1)) = 1/(x + 1).'),
  ('x³ − x² − 4x + 4 = 0 denkleminin gerçek sayılardaki çözüm kümesi hangisidir?', '{−2, 1, 2}', ['{1, 2}', '{−1, 2, 4}', '{−2, −1, 2}'], 'Gruplama ile x²(x − 1) − 4(x − 1) = (x − 1)(x − 2)(x + 2) = 0 bulunur. Kökler 1, 2 ve −2\'dir.'),
  ('x⁴ − 2x³ + x² = 0 denkleminin birbirinden farklı kaç gerçek kökü vardır?', '2', ['4', '3', '−1'], 'İfade x²(x² − 2x + 1) = x²(x − 1)² olarak ayrılır. Farklı kökler yalnız 0 ve 1\'dir; ikisi de çift katlıdır.'),
  ('Sıfırdan farklı bir sabit polinom ile sıfır polinomunun kökleri için hangisi doğrudur?', 'Birincinin kökü yoktur; ikincisinde her sayı köktür', ['İkisinin de kökü yoktur', 'İkisinde de her sayı köktür', 'Birincinin tek kökü sıfırdır; ikincinin hiç kökü yoktur'], 'P(x) = c ≠ 0 hiçbir x için sıfır olmaz. Sıfır polinomu ise her x için 0 değerini aldığından her sayı onun köküdür.'),
  ('Toplamları sıfır, karelerinin toplamı 6 olan üç sayının ikişerli çarpımlarının toplamını bulunuz.', '−3', ['3', '−6', '−12'], '(a + b + c)² = a² + b² + c² + 2(ab + bc + ca) eşitliğinden 0 = 6 + 2(ab + bc + ca) ve toplam −3 olur.'),
  ('a + b + c = 0 koşulunu sağlayan sayılar için (a + b)(b + c)(c + a) çarpımı neye eşittir?', '−abc', ['abc', '0', '−3abc'], 'a + b = −c, b + c = −a, c + a = −b olduğundan çarpım (−c)(−a)(−b) = −abc\'dir.'),
  ('2 + √3 sayısı ile çarpmaya göre tersinin toplamı, tersin paydası rasyonel yapılarak hesaplanırsa ne çıkar?', '4', ['2√3', '4 + 2√3', '2'], '1/(2 + √3) = (2 − √3)/(4 − 3) = 2 − √3\'tür. Toplam (2 + √3) + (2 − √3) = 4 olur.'),
  ('Sıfırdan farklı x için x + 1/x ile x² + 1/x² − 1 ifadelerinin çarpımı, küp toplamı özdeşliği düşünülerek nasıl yazılır?', 'x³ + 1/x³', ['x³ − 1/x³', 'x³ + 1/x³ + 1', 'x² + 1/x²'], 'a³ + b³ = (a + b)(a² − ab + b²) özdeşliği a = x, b = 1/x ile kullanılır; ab = 1 olduğundan orta terim −1\'dir.'),
  ('Toplamın küpünden x³ ve y³ çıkarıldığında kalan (x + y)³ − x³ − y³ ifadesi hangi çarpıma eşittir?', '3xy(x + y)', ['3xy', '3x²y + 3xy² + xy', 'xy(x + y)'], '(x + y)³ = x³ + 3x²y + 3xy² + y³ olduğundan fark 3x²y + 3xy² = 3xy(x + y)\'dir.'),
  ('Ardışık üç tam sayının çarpımı ile ortadaki sayının küpü arasındaki fark (n − 1)n(n + 1) − n³ neye eşittir?', '−n', ['n', '−1', 'n² − n'], '(n − 1)(n + 1) = n² − 1 olduğundan çarpım n³ − n\'dir; n³ çıkarılınca −n kalır.'),
  ('Kenarı 20 cm olan kare bir kartonun dört köşesinden kenarı x cm olan kareler kesilip kenarlar katlanarak üstü açık bir kutu yapılıyor. Kutunun hacmini veren polinomun derecesi ve baş katsayısı nedir?', 'Derece 3, baş katsayı 4', ['Derece 2, baş katsayı 4', 'Derece 3, baş katsayı 1', 'Derece 3, baş katsayı −4'], 'Taban kenarı 20 − 2x, yükseklik x olduğundan V(x) = x(20 − 2x)² = 4x³ − 80x² + 400x olur.'),
  ('Sabit terimden x⁹⁹\'a kadar bütün kuvvetleri katsayısı 1 olarak içeren x⁹⁹ + x⁹⁸ + ⋯ + x + 1 toplamı x − 1\'e bölünürse kalan ne olur?', '100', ['99', '1', '−100'], 'Kalan P(1)\'dir. Polinomda x⁹⁹\'dan x⁰\'a kadar 100 terim vardır ve her biri x = 1\'de 1 değerini alır.'),
  ('a² − 2a = 3 bilgisi verildiğinde, a ortak çarpanı alınarak a³ − 2a² − 3a için hangi değere ulaşılır?', '0', ['3', '9', '−3'], 'a³ − 2a² − 3a = a(a² − 2a − 3) yazılır. Parantez içi 3 − 3 = 0 olduğundan değer 0\'dır.'),
  ('Dört terimli a³ − a²b − ab² + b³ ifadesinde ilk ikisinden a², son ikisinden −b² dışarı alınırsa sonuç hangi çarpıma varır?', '(a − b)²(a + b)', ['(a + b)²(a − b)', '(a − b)³', '(a² − b²)(a + b)'], 'a²(a − b) − b²(a − b) = (a − b)(a² − b²) = (a − b)²(a + b) olur.'),
  ('x⁶ + 1 ifadesi x² cinsinden bir küp toplamı olarak düşünülürse hangi çarpıma ayrılır?', '(x² + 1)(x⁴ − x² + 1)', ['(x³ + 1)(x³ − 1)', '(x² + 1)(x⁴ + x² + 1)', '(x² + 1)(x⁴ − x² + 1)(x + 1)'], 'x⁶ + 1 = (x²)³ + 1³ = (x² + 1)((x²)² − x² + 1) olur.'),
  ('x − 1 ve y + 1 birer blok olarak alınırsa (x − 1)² − 2(x − 1)(y + 1) + (y + 1)² toplamı neyin karesine eşit olur?', 'x − y − 2', ['x − y', 'x + y', 'x − y − 2xy'], 'a = x − 1, b = y + 1 denirse ifade (a − b)² olur. a − b = x − 1 − y − 1 = x − y − 2\'dir.'),
  ('x² − 2xy + y² − x + y ifadesi x − y parantezine alınarak nasıl çarpanlarına ayrılır?', '(x − y)(x − y − 1)', ['(x − y)(x − y + 1)', '(x + y)(x − y − 1)', '(x − y)²(x − y − 1)'], 'İlk üç terim (x − y)², son iki terim −(x − y)\'dir. Ortak çarpan alınınca (x − y)(x − y − 1) bulunur.'),
  ('x ≠ y için x²/(x − y) + y²/(y − x) toplamı neye eşittir?', 'x + y', ['x − y', '(x² + y²)/(x − y)', '1'], 'İkinci kesir −y²/(x − y) olarak yazılır. Toplam (x² − y²)/(x − y) = x + y olur.'),
  ('37³ − 17³ sayısı aşağıdakilerden hangisine kesinlikle tam bölünür?', '20', ['17', '27', '370'], 'a³ − b³ = (a − b)(a² + ab + b²) olduğundan 37³ − 17³ sayısı 37 − 17 = 20\'ye bölünür.'),
  ('n pozitif tam sayı olmak üzere 7ⁿ − 1 sayısı her zaman hangi sayıya bölünür?', '6', ['7', '8', '14'], 'xⁿ − 1 = (x − 1)(xⁿ⁻¹ + ⋯ + 1) özdeşliğinde x = 7 alınırsa 7ⁿ − 1\'in 7 − 1 = 6\'nın katı olduğu görülür.'),
  ('n tek bir pozitif tam sayı ise 2ⁿ + 1 sayısı her zaman hangi sayıya bölünür?', '3', ['5', '9', '2ⁿ'], 'n tekken xⁿ + 1 ifadesi x + 1\'e bölünür. x = 2 için 2ⁿ + 1, 3\'ün katıdır; örneğin 2⁵ + 1 = 33.'),
  ('(x² − 4x + 4)(x² − 4) polinomunda x = 2 kökünün katlılığı kaçtır?', '3', ['2', '4', '−2'], 'x² − 4x + 4 = (x − 2)² ve x² − 4 = (x − 2)(x + 2) olduğundan polinom (x − 2)³(x + 2)\'dir.'),
  ('(a + b)² = a² + b² eşitliği hangi koşulda doğru olur?', 'ab = 0 olduğunda', ['a = b olduğunda', 'a + b = 1 olduğunda', 'Her zaman doğrudur'], '(a + b)² − (a² + b²) = 2ab\'dir. Bu fark yalnız ab = 0, yani a ya da b sıfır olduğunda sıfırdır.'),
  ('Bir tam sayının küpü ile kendisinin farkı 336\'dır. Bu pozitif sayı kaçtır?', '7', ['6', '8', '12'], 'n³ − n = (n − 1)n(n + 1) olduğundan ardışık üç sayının çarpımı 336 = 6·7·8 olmalıdır; n = 7 bulunur.'),
  ('Ardışık iki çift sayının karelerinin farkı 52\'dir. Küçük sayı kaçtır?', '12', ['13', '14', '−14'], '(n + 2)² − n² = 4n + 4 = 52 eşitliğinden n = 12 bulunur; 14² − 12² = 196 − 144 = 52.'),
  ('Her x için x³ = a(x − 1)³ + b(x − 1)² + c(x − 1) + d eşitliği sağlanıyor. c kaçtır?', '3', ['1', '0', '−3'], 't = x − 1 yazılırsa x³ = (t + 1)³ = t³ + 3t² + 3t + 1 olur. t\'nin katsayısı c = 3\'tür.'),
  ('P(x) = x² − 1 ve Q(x) = x + 1 için P(Q(x)) − Q(P(x)) farkı hangisidir?', '2x', ['0', '2x + 2', '−2x'], 'P(Q(x)) = (x + 1)² − 1 = x² + 2x, Q(P(x)) = x² − 1 + 1 = x²\'dir. Fark 2x olur; yani bileşke işlemi değişmeli değildir.'),
  ('Payı 2026² − 4, paydası 2026·2028 olan sayısal kesir iki kare farkı kullanılarak sadeleştirilirse hangi sonuç elde edilir?', '1012/1013', ['1013/1014', '2024/2028', '2026/2028'], '2026² − 4 = (2026 − 2)(2026 + 2) = 2024·2028\'dir. 2028 sadeleşince 2024/2026 = 1012/1013 kalır.'),
  ('x + y ≠ 0 olmak üzere x² − y² + x + y = 0 ise x − y farkı kaçtır?', '−1', ['1', '0', '−1/2'], 'İfade (x + y)(x − y) + (x + y) = (x + y)(x − y + 1) olur. x + y ≠ 0 olduğundan x − y + 1 = 0 ve x − y = −1\'dir.'),
  ('x ve y gerçek sayılar olmak üzere xy + 1 = x + y eşitliği sağlanıyorsa hangisi kesinlikle doğrudur?', 'x = 1 ya da y = 1', ['x = y', 'x + y = 1', 'x = 1 ve y = 1 birlikte'], 'Eşitlik xy − x − y + 1 = 0, yani (x − 1)(y − 1) = 0 biçiminde yazılır. Çarpım sıfırsa çarpanlardan biri sıfırdır.'),
  ('a + b ≠ 0 olmak üzere a³ + b³ = a + b ise a² − ab + b² ifadesinin değeri kaçtır?', '1', ['0', 'a + b', 'ab'], 'a³ + b³ = (a + b)(a² − ab + b²) olduğundan (a + b)(a² − ab + b²) = a + b ve a + b sıfır olmadığından a² − ab + b² = 1\'dir.'),
  ('Dördüncü kuvveti 1 olan karmaşık sayıların tümü, yani x⁴ − 1 = 0 eşitliğinin karmaşık çözümleri hangileridir?', '{1, −1, i, −i}', ['{1, −1}', '{1, i}', '{1, −1, 2i, −2i}'], 'x⁴ − 1 = (x − 1)(x + 1)(x² + 1) olur; x² + 1 = 0 eşitliği x = ±i verir.'),
  ('x³ − 1 = 0 denkleminin gerçek olmayan iki kökünün toplamı kaçtır?', '−1', ['0', '1', '1 + i'], 'Üç kökün toplamı 0\'dır ve gerçek kök 1\'dir. Diğer iki kökün toplamı 0 − 1 = −1 olur; bunlar x² + x + 1 = 0\'ın kökleridir.'),
  ('ω sayısı x² + x + 1 = 0 denkleminin bir kökü ise ω³ kaçtır?', '1', ['−1', '0', 'ω'], 'x³ − 1 = (x − 1)(x² + x + 1) olduğundan x² + x + 1\'in her kökü x³ − 1 = 0 denklemini de sağlar; ω³ = 1.'),
  ('Bütün katsayıları pozitif olan bir polinomun pozitif kökleri hakkında ne söylenebilir?', 'Hiç pozitif kökü yoktur', ['En az bir pozitif kökü vardır', 'Tek pozitif kökü 1\'dir', 'Kökleri yalnız pozitiftir'], 'x > 0 için her terim pozitif olacağından toplam da pozitiftir ve sıfır olamaz. Bu yüzden pozitif kök bulunmaz.'),
  ('P(x) = 3x − 1 için polinomun karesi ile x² noktasındaki değeri arasındaki fark, yani [P(x)]² − P(x²), nedir?', '6x² − 6x + 2', ['0', '6x² − 6x', '6x² − 6x + 1'], '[P(x)]² = 9x² − 6x + 1, P(x²) = 3x² − 1\'dir. Fark 6x² − 6x + 2 olur.'),
  ('Katsayıları 1, −4, 6, −4, 1 olan dördüncü derece polinomu x = 11\'de hesaplamanın en kısa yolu hangi sonucu verir?', '10 000', ['14 641', '1 000', '100 000'], 'Katsayılar 1, −4, 6, −4, 1 olduğundan P(x) = (x − 1)⁴\'tür. P(11) = 10⁴ = 10 000.'),
  ('Bir gerçek sayı ile tersinin toplamı −2 ise bu sayı nedir?', '−1', ['1', '−2', '−1/2'], 'x ile çarpılırsa x² + 2x + 1 = 0, yani (x + 1)² = 0 olur ve x = −1 bulunur.'),
  ('x³ + ax² + bx − 6 polinomunun çarpanlarından ikisi x − 1 ve x − 2\'dir. Üçüncü birinci dereceden çarpan hangisidir?', 'x − 3', ['x + 3', 'x − 6', 'x² − 3'], 'Polinom (x − 1)(x − 2)(x − r) biçimindedir ve sabit terimi −2r = −6 olmalıdır. Buradan r = 3 bulunur.'),
  ('Tam sayı katsayılı, baş katsayısı 1 ve sabit terimi 7 olan üçüncü dereceden bir polinomun kaç tam sayı kök adayı vardır?', '4', ['2', '7', '14'], 'Monik polinomlarda tam sayı kökler sabit terimin bölenleridir: ±1 ve ±7. Toplam dört aday vardır.'),
  ('Yerden yukarı atılan bir topun t saniyedeki yüksekliği h(t) = −5t² + 20t metredir. İfade çarpanlarına ayrılarak top hangi anda yeniden yere düşer?', '4. saniyede', ['2. saniyede', '5. saniyede', '20. saniyede'], 'h(t) = −5t(t − 4)\'tür. Yükseklik t = 0 (atış anı) ve t = 4\'te sıfırdır; top 4. saniyede yere düşer.'),
  ('x³ − 5x² + 8x − 4 polinomu Horner yöntemiyle x − 2\'ye bölünüyor, sonra elde edilen bölüm yeniden x − 2\'ye bölünüyor. İkinci bölmede de kalan sıfır çıkması neyi gösterir?', '2 sayısı en az çift katlı bir köktür', ['2 sayısı polinomun kökü değildir', 'Polinomun yalnız bir kökü vardır', '2 sayısı basit (tek katlı) bir köktür'], 'İlk bölmede bölüm x² − 3x + 2, ikinci bölmede x − 1 bulunur ve iki kalan da sıfırdır. Bu, (x − 2)²\'nin çarpan olduğunu gösterir: polinom (x − 2)²(x − 1)\'dir.'),
  ('(x + 2)(x − 2)(x² + 2x + 4)(x² − 2x + 4) çarpımı hangi iki terimliye eşittir?', 'x⁶ − 64', ['x⁶ + 64', 'x⁴ − 16', '(x³ − 8)²'], '(x − 2)(x² + 2x + 4) = x³ − 8 ve (x + 2)(x² − 2x + 4) = x³ + 8\'dir. Çarpımları (x³)² − 8² = x⁶ − 64.'),
  ('Kalan teoreminin (P(x)\'in x − a ile bölümünden kalanın P(a) olması) kanıtı hangi adıma dayanır?', 'P(x) = (x − a)Q(x) + R eşitliğinde x = a yazılması', ['P(x)\'in türevinin a\'da sıfır olması', 'P(a)\'nın her zaman sıfır olması', 'Bölümün her durumda sabit bir polinom olması'], 'Bölme özdeşliğinde R sabittir. x = a yazılınca (a − a)Q(a) = 0 olur ve P(a) = R elde edilir.'),
  ('(x − a)(x − b)(x − c) çarpımı açıldığında x\'li terimin katsayısı hangisidir?', 'ab + bc + ca', ['a + b + c', '−(ab + bc + ca)', '−abc'], 'x, üç çarpanın birinden x ve diğer ikisinden sabit seçilerek oluşur: (−a)(−b) + (−b)(−c) + (−a)(−c) = ab + bc + ca.'),
  ('Monik üçüncü dereceden bir polinomun kökler toplamı 3, ikişerli çarpımlar toplamı 3 ve kökler çarpımı 1\'dir. Kökleri hakkında hangisi doğrudur?', 'Üç kök de 1\'dir', ['Kökler 1, 2 ve 3\'tür', 'Kökler −1, 1 ve 3\'tür', 'Yalnız bir kökü 1\'dir'], 'Bu değerlerle polinom x³ − 3x² + 3x − 1 = (x − 1)³ olur; 1 üç katlı köktür.'),
  ('x³ + bx² + cx + d polinomunun üç kökünün (karmaşık kökler dâhil) aritmetik ortalaması hangisidir?', '−b/3', ['b/3', '−d/3', '−b/(3d)'], 'Kökler toplamı −b olduğundan ortalama −b/3\'tür.'),
  ('Ardışık üç tam sayının (n − 1, n, n + 1) karelerinin toplamı hangi ifadeye eşittir?', '3n² + 2', ['3n²', '3n² + 1', '3n² + 2n + 2'], '(n − 1)² + (n + 1)² = 2n² + 2\'dir; n² eklenince 3n² + 2 bulunur.'),
  ('Ardışık iki tam sayıdan küçüğü n\'dir. Bu iki sayının çarpımına büyük olanın eklenmesiyle elde edilen n(n + 1) + (n + 1) toplamı her zaman nedir?', 'Büyük sayının karesi', ['Küçük sayının karesi', 'İki sayının toplamı', 'Her zaman bir tek sayı'], 'Ortak çarpan n + 1 alınınca (n + 1)(n + 1) = (n + 1)² bulunur.'),
  ('(x² + 3x + 1)² − (x² + 3x − 1)² ifadesi sadeleştirildiğinde hangisi elde edilir?', '4x² + 12x', ['4', '2x² + 6x', '4x² + 12x + 2'], 'İki kare farkıyla [(x² + 3x + 1) − (x² + 3x − 1)]·[(x² + 3x + 1) + (x² + 3x − 1)] = 2·(2x² + 6x) = 4x² + 12x.'),
  ('Sabit terimi 9 olan x⁴ − 9 iki terimlisinin gerçek sayılardaki tam ayrışımı hangisidir?', '(x² + 3)(x − √3)(x + √3)', ['(x² − 3)(x² + 3)', '(x − 3)(x + 3)(x² + 3)', '(x − √3)(x + √3)(x² + 3)²'], 'x⁴ − 9 = (x² − 3)(x² + 3) ve x² − 3 = (x − √3)(x + √3) olur; x² + 3 gerçek sayılarda ayrılamaz.'),
  ('Yüksekliği h olan bir silindirin taban yarıçapı r\'den r + 1\'e çıkarılırsa hacmi ne kadar artar?', 'πh(2r + 1)', ['πh', 'πh(r + 1)', '2πhr'], 'Yeni hacim πh(r + 1)², eski hacim πhr²\'dir. Fark πh[(r + 1)² − r²] = πh(2r + 1) olur.'),
  ('Gerçek katsayılı bir polinomun kökleri arasında 1 + i ve 2 bulunuyor. Bu polinomun derecesi en az kaçtır?', '3', ['2', '4', '5'], 'Gerçek katsayılı polinomlarda 1 + i ile birlikte eşleniği 1 − i de köktür. 2 ile birlikte en az üç kök vardır.'),
  ('x ≠ 2 için x/(x − 2) kesri 1 + A/(x − 2) biçiminde yazılabiliyorsa A kaçtır?', '2', ['−2', '1', 'x'], 'x = (x − 2) + 2 olduğundan x/(x − 2) = 1 + 2/(x − 2)\'dir; bu, x\'in x − 2\'ye bölümünde bölüm 1, kalan 2 olmasının sonucudur.'),
  ('Katsayıları sırasıyla 1, −1, 1, −1 olan kübik denklemi, yani x³ − x² + x − 1 = 0 eşitliğini sağlayan kaç gerçek sayı vardır?', '1', ['3', '2', '0'], 'Gruplama ile x²(x − 1) + (x − 1) = (x − 1)(x² + 1) olur. x² + 1 gerçek sayılarda sıfır olmadığından yalnız x = 1 gerçek köktür.'),
  ('2026³ + 1 sayısının 2025\'e bölümünden kalan kaçtır?', '2', ['1', '0', '2026'], 'P(x) = x³ + 1 polinomu düşünülürse 2026 ≡ 1 (mod 2025) olduğundan kalan P(1) = 1 + 1 = 2\'dir; bu, x − 1\'e bölmedeki kalan teoreminin sayısal karşılığıdır.'),
  ('x ≠ ±1 için (x³ − 1)/(x − 1) − (x³ + 1)/(x + 1) farkı neye eşittir?', '2x', ['2', '0', '2x²'], 'İlk bölüm x² + x + 1, ikinci bölüm x² − x + 1\'dir. Farkları 2x olur.'),
  ('Bir r sayısının P(x) polinomunun tam olarak k katlı kökü olması için hangi koşul gerekir?', '(x − r)ᵏ çarpandır ama (x − r)ᵏ⁺¹ değildir', ['P(r) = k olmasıdır', 'r\'nin k farklı polinomun kökü olmasıdır', 'P(x)\'in derecesinin k olmasıdır'], 'Katlılık, x − r çarpanının polinomda kaç kez tekrarlandığını gösterir: (x − r)ᵏ bölüp (x − r)ᵏ⁺¹ bölmüyorsa r, k katlı köktür.'),
  ('Katsayıları baştan ve sondan okunduğunda aynı olan (simetrik) bir polinomun sıfırdan farklı kökü r ise hangi sayı da kesinlikle köktür?', '1/r', ['−r', 'r²', '−1/r'], 'Simetrik polinomda xⁿP(1/x) = P(x)\'tir. P(r) = 0 ise P(1/r) = 0 da olur.'),
  ('Polinom bölmesindeki \'kalanın derecesi bölenin derecesinden küçüktür\' koşulu, tam sayılardaki kalanlı bölmede hangi koşula karşılık gelir?', 'Kalanın bölenden küçük olması', ['Bölümün bölenden küçük olması', 'Bölünenin bölenden büyük olması', 'Kalanın sıfır olması'], 'Tam sayılarda 0 ≤ kalan < bölen koşulu bölüm ve kalanı tek kılar; polinomlarda aynı işi derece koşulu görür.'),
  ('İkinci dereceden bir P(x) polinomunun kökleri 1 ve 2\'dir ve P(0) = 6\'dır. P(3) kaçtır?', '6', ['3', '12', '2'], 'P(x) = a(x − 1)(x − 2) yazılır. P(0) = 2a = 6\'dan a = 3 olur; P(3) = 3·2·1 = 6\'dır.'),
  ('Kareleri toplamı 10, farkları 2 olan iki sayının toplamının karesini, (x + y)² + (x − y)² = 2(x² + y²) özdeşliğiyle bulunuz.', '16', ['12', '8', '20'], '(x + y)² + (x − y)² = 2(x² + y²) özdeşliğinden (x + y)² = 20 − 4 = 16 bulunur.'),
  ('Oranı a/b = 2/3 olan iki sayı için toplamın karesinin kareler farkına bölümü, (a + b)²/(a² − b²), hangi sayıya eşittir?', '−5', ['5', '−1/5', '5/3'], '(a + b)²/((a − b)(a + b)) = (a + b)/(a − b) olur. a = 2k, b = 3k alınırsa 5k/(−k) = −5 bulunur.'),
  ('Kare biçimli bir bahçenin kenarı 3 m artırılınca alanı 39 m² artıyor. Bahçenin ilk kenarı kaç metredir?', '5', ['6', '4', '13'], '(x + 3)² − x² = 6x + 9 = 39 eşitliğinden x = 5 bulunur.'),
  ('Bir öğrenci 2(x + 3)² ifadesini (2x + 6)² olarak yazıyor. Bu dönüşüm hakkında hangisi doğrudur?', 'Yanlıştır; (2x + 6)² = 4(x + 3)²\'dir', ['Doğrudur', 'Yalnız x = 0 için yanlıştır', 'Yanlıştır; doğrusu (2x + 3)²\'dir'], 'Katsayı karenin içine alınırken kendi karekökü olarak girer: 2(x + 3)² = (√2(x + 3))². (2x + 6)² ise 2² = 4 katı verir.'),
  ('Üç polinomun, x − 1, x + 1 ve x² + 1\'in, her birine tam bölünen en düşük dereceli monik polinom nedir?', 'x⁴ − 1', ['x² − 1', 'x⁴ + 1', '(x² + 1)²'], 'Üç polinom aralarında asal olduğundan EKOK çarpımlarıdır: (x − 1)(x + 1)(x² + 1) = (x² − 1)(x² + 1) = x⁴ − 1.'),
  ('Beşinci kuvveti kendisine eşit olan gerçek sayıların, yani x⁵ = x eşitliğini sağlayanların sayısı kaçtır?', '3', ['5', '2', '1'], 'x⁵ − x = x(x − 1)(x + 1)(x² + 1) olur. Gerçek kökler 0, 1 ve −1\'dir; x² + 1 gerçek kök vermez.'),
  ('Bir polinomun bütün kökleri katlılıklarıyla birlikte biliniyorsa polinom hakkında ne söylenebilir?', 'Baş katsayısı dışında tek türlü belirlenir', ['Tamamen tek türlü belirlenir', 'Derecesi bilinemez', 'Sabit terimi her zaman 1\'dir'], 'Kökler r₁, …, rₙ ise P(x) = a(x − r₁)⋯(x − rₙ) olur. Kökler aynı kalırken a baş katsayısı değiştirilebilir.'),
  ('Köklü bir iki terimli olan √3 + 1 sayısının küpü hesaplanırsa hangi sonuç bulunur?', '10 + 6√3', ['4 + 3√3', '3√3 + 1', '10 + 2√3'], '(a + b)³ = a³ + 3a²b + 3ab² + b³ ile 3√3 + 3·3·1 + 3·√3·1 + 1 = 10 + 6√3 bulunur.'),
  ('n pozitif tam sayı olmak üzere (x + 1)(x + 2)(x + 3)⋯(x + n) çarpımının sabit terimi nedir?', 'n!', ['n', 'n(n + 1)/2', '2ⁿ'], 'Sabit terim her çarpandan sabit seçilerek oluşur: 1·2·3⋯n = n!.'),
  ('Üç iki terimlinin, 1 + x, 1 + x² ve 1 + x³\'ün çarpımında x\'in üçüncü kuvveti kaç farklı seçimle oluşur (yani katsayısı nedir)?', '2', ['1', '3', '0'], 'x³ iki yolla oluşur: üçüncü çarpandan x³ (diğerlerinden 1) ya da birinci çarpandan x ve ikinciden x². Katsayı 2\'dir.'),
  ('x⁴ + x³ + x + 1 dört terimlisinde x³ ortak çarpanı ilk iki terimden alınıp küp toplamı uygulanırsa sonuç ne olur?', '(x + 1)²(x² − x + 1)', ['(x + 1)(x³ − 1)', '(x − 1)²(x² + x + 1)', '(x + 1)²(x² + x + 1)'], 'x³(x + 1) + (x + 1) = (x + 1)(x³ + 1) ve x³ + 1 = (x + 1)(x² − x + 1) olduğundan (x + 1)²(x² − x + 1) bulunur.'),
  ('(x² − 5x + 5)² − 1 ifadesi tamamen çarpanlarına ayrıldığında kaç tane farklı birinci dereceden çarpan elde edilir?', '4', ['2', '3', '5'], 'İki kare farkıyla (x² − 5x + 4)(x² − 5x + 6) = (x − 1)(x − 4)(x − 2)(x − 3) olur.'),
  ('x ≠ 0 için (x⁴ − x)/(x² + x + 1) bölümü hangi polinoma eşittir?', 'x(x − 1)', ['x(x + 1)', 'x² − 1', 'x³ − 1'], 'x⁴ − x = x(x³ − 1) = x(x − 1)(x² + x + 1) olduğundan x² + x + 1 sadeleşir.'),
  ('Latin alfabesinin 26 harfi kullanılarak yazılan (x − a)(x − b)(x − c)⋯(x − z) çarpımının değeri nedir?', '0', ['x²⁶', 'abc⋯z', '26x'], 'Çarpanlardan biri (x − x)\'tir ve bu çarpan sıfır olduğundan bütün çarpım sıfırdır.'),
  ('Kenarı a olan bir kareden köşesindeki kenarı b olan kare kesiliyor; kalan L biçimli parça kesilip yeniden düzenlenerek bir dikdörtgen yapılıyor. Bu dikdörtgenin kenarları nedir?', 'a − b ve a + b', ['a ve b', 'a − b ve a − b', 'a + b ve b'], 'L parçası, eni a − b olan iki dikdörtgene ayrılır; bunlar uç uca konunca kenarları a − b ve a + b olan bir dikdörtgen oluşur. Bu, a² − b² = (a − b)(a + b) özdeşliğinin şekilsel gösterimidir.'),
  ('n³ dizisinin (1, 8, 27, 64, 125, …) ardışık farkları üç kez alınırsa hangi sabit sayı elde edilir?', '6', ['3', '1', '27'], 'Birinci farklar 7, 19, 37, 61; ikinci farklar 12, 18, 24; üçüncü farklar sabit 6\'dır. Genel olarak n. dereceden monik polinomun n. farkları n!\'e eşittir.'),
  ('Gerçek katsayılı bir P(x) polinomu için P(i) = 0 ise aşağıdakilerden hangisi kesinlikle bir çarpandır?', 'x² + 1', ['x + 1', 'x − 1', 'x² − 1'], 'Gerçek katsayılarda i ile birlikte −i de köktür; (x − i)(x + i) = x² + 1 çarpanı ortaya çıkar.'),
  ('x² + 9 ifadesi karmaşık katsayılı birinci dereceden çarpanlara nasıl ayrılır?', '(x − 3i)(x + 3i)', ['(x − 3)(x + 3)', '(x + 3i)²', '(x − 9i)(x + i)'], 'x² + 9 = x² − (3i)² olduğundan iki kare farkı karmaşık sayılarda (x − 3i)(x + 3i) verir.'),
  ('Rasyonel kök teoremi x² − 2 polinomuna uygulandığında hangi sonuç elde edilir?', '√2 irrasyoneldir', ['√2 rasyoneldir', 'x² − 2\'nin kökü yoktur', '2 sayısı tam karedir'], 'Olası rasyonel kökler ±1 ve ±2\'dir ve hiçbiri x² − 2\'yi sıfır yapmaz. Oysa √2 bir köktür; demek ki √2 rasyonel olamaz.'),
  ('x ≠ ±1 için (x + 1)/(x − 1) − (x − 1)/(x + 1) farkı hangisine eşittir?', '4x/(x² − 1)', ['2/(x² − 1)', '4/(x² − 1)', '2x/(x² − 1)'], 'Ortak payda x² − 1 ile pay (x + 1)² − (x − 1)² = 4x olur.'),
  ('y ≠ 0 olmak üzere x² + 4y² = 4xy ise x/y oranı kaçtır?', '2', ['4', '1/2', '−2'], 'Eşitlik x² − 4xy + 4y² = 0, yani (x − 2y)² = 0 olur ve x = 2y bulunur.'),
  ('13³ − 8³ − 5³ işlemi, toplamı sıfır olan üç sayının küpleri toplamı özdeşliğiyle hesaplanırsa sonuç kaçtır?', '1560', ['520', '0', '2197'], '13 + (−8) + (−5) = 0 olduğundan 13³ + (−8)³ + (−5)³ = 3·13·(−8)·(−5) = 1560 bulunur.'),
  ('İkinci dereceden bir polinomun ardışık tam sayılardaki değerlerinin ikinci farkları hep 6\'dır. Bu polinomun baş katsayısı kaçtır?', '3', ['6', '2', '12'], 'ax² + bx + c için ikinci farklar 2a\'dır. 2a = 6\'dan a = 3 bulunur.'),
  ('On ikinci kuvvetten bir eksik olan x¹² − 1, x⁴ = t dönüşümüyle x⁴ − 1\'e bölünürse bölüm ne olur?', 'x⁸ + x⁴ + 1', ['x⁸ + 1', 'x³', 'x⁸ − x⁴ + 1'], 't = x⁴ denirse t³ − 1 = (t − 1)(t² + t + 1) olur; bölüm t² + t + 1 = x⁸ + x⁴ + 1\'dir.'),
  ('x² + 6x + 5 ifadesi önce (x + 3)² − 4 biçimine getirilip sonra çarpanlarına ayrılıyor. Bu yöntemle hangi sonuç bulunur?', '(x + 1)(x + 5)', ['(x + 3)(x + 2)', '(x + 3 − 4)(x + 3 + 4)', '(x − 1)(x − 5)'], '(x + 3)² − 2² iki kare farkıdır: (x + 3 − 2)(x + 3 + 2) = (x + 1)(x + 5).'),
  ('Birinci dereceden bir P(x) polinomu için P(2) = 3\'tür ve her x için P(x + 1) − P(x) = 4\'tür. P(x) hangisidir?', '4x − 5', ['4x + 3', '3x − 3', '4x − 2'], 'P(x) = ax + b ise P(x + 1) − P(x) = a = 4 olur. P(2) = 8 + b = 3\'ten b = −5 bulunur.'),
  ('Altın oran φ = (1 + √5)/2 hangi tam sayı katsayılı polinomun köküdür?', 'x² − x − 1', ['x² + x − 1', 'x² − 2x − 1', 'x² − 5'], 'φ² = (6 + 2√5)/4 = (3 + √5)/2 = φ + 1 olduğundan φ² − φ − 1 = 0\'dır.'),
  ('Bir öğrenci 2x² + 3x + 4 polinomunu x + 1\'e bölüp bölümü 2x + 1, kalanı 2 buluyor. x = 0 yazılarak yapılan denetim ne gösterir?', 'Sol taraf 4, sağ taraf 3 çıkar; bir hata vardır', ['İki taraf da 4 çıkar; sonuç doğrudur', 'İki taraf da 3 çıkar; sonuç doğrudur', 'Denetim için x = −1 dışında değer kullanılamaz'], 'x = 0\'da bölünen 4, bölen·bölüm + kalan ise 1·1 + 2 = 3\'tür. Doğru kalan P(−1) = 2 − 3 + 4 = 3 olmalıdır.'),
  ('Dördüncü dereceden a⁴ − 2a²b² + b⁴ ifadesi önce bir tam kare, sonra kare farkı olarak görülürse hangi çarpıma ayrılır?', '(a − b)²(a + b)²', ['(a² + b²)²', '(a − b)⁴', '(a² − b²)(a² + b²)'], 'İfade (a² − b²)²\'dir. a² − b² = (a − b)(a + b) olduğundan karesi (a − b)²(a + b)² olur.'),
  ('Tam sayılardaki asal sayılar kavramının polinomlardaki karşılığı aşağıdakilerden hangisidir?', 'İndirgenemez polinom', ['Monik polinom', 'Sabit polinom', 'Homojen polinom'], 'Asal sayılar yalnız 1 ve kendisine bölünür; indirgenemez polinomlar da sabit ve kendi sabit katları dışında daha düşük dereceli çarpanlara ayrılamaz.'),
  ('Bir rasyonel ifadenin en sade biçimde olması ne anlama gelir?', 'Pay ile paydanın sabitten başka ortak böleni yoktur', ['Payın derecesi paydanınkinden küçüktür', 'Paydanın kökü yoktur', 'Pay ile payda aynı derecedendir'], 'Sadeleştirme, pay ve paydanın EBOB\'u ile bölmektir. EBOB sabit olduğunda daha fazla sadeleştirme yapılamaz.'),
  ('İki değişkenli x²y + xy² + x + y toplamında ilk iki terimden xy alınırsa ortaya çıkan ortak parantezle sonuç ne olur?', '(x + y)(xy + 1)', ['(x + y)(xy − 1)', '(xy + 1)²', '(x + 1)(y + 1)(x + y)'], 'xy(x + y) + (x + y) = (x + y)(xy + 1) olur.'),
  ('a²b − ab² − a + b ifadesinde ab(a − b) ve −(a − b) parçaları birleştirilirse hangi çarpım elde edilir?', '(a − b)(ab − 1)', ['(a − b)(ab + 1)', '(a + b)(ab − 1)', 'ab(a − b) − 1'], 'ab(a − b) − (a − b) = (a − b)(ab − 1) bulunur.'),
  ('Dört noktada kare sayıları veren (1→1, 2→4, 3→9, 4→16) ve derecesi en fazla üç olan polinomun 5\'teki değeri nedir?', '25', ['24', '26', '36'], 'x² polinomu bu dört koşulu sağlar. Derecesi en çok 3 olan ve dört noktada aynı değerleri alan polinom tek olduğundan P(x) = x² ve P(5) = 25\'tir.'),
  ('Derecesi en çok 2 olan bir P(x) polinomu için P(1) = P(2) = P(3) = 7 ise P(x) hakkında hangisi doğrudur?', 'P(x) = 7 sabit polinomudur', ['P(x) = 7x', 'P(x) = x² + 7', 'P(x)\'in kökleri 1, 2 ve 3\'tür'], 'P(x) − 7 polinomunun derecesi en çok 2\'dir ama üç kökü vardır; bu ancak sıfır polinomu olmasıyla mümkündür.'),
  ('z karmaşık sayısı x² − x + 1 = 0 eşitliğini sağlıyor. x + 1 ile çarpım düşünülürse z\'nin küpü hangi değere eşit çıkar?', '−1', ['1', '0', 'z'], '(x + 1)(x² − x + 1) = x³ + 1 olduğundan z³ + 1 = 0 ve z³ = −1\'dir.'),
  ('a + b + c ile a − b − c ifadelerinin kareleri farkı sadeleştirildiğinde hangi çarpım elde edilir?', '4a(b + c)', ['4ab + 4ac + 4bc', '4a²', '2a(b + c)'], 'İki kare farkıyla [(a + b + c) − (a − b − c)]·[(a + b + c) + (a − b − c)] = 2(b + c)·2a = 4a(b + c).'),
  ('Eski çağlarda kareler tablosuyla çarpma yapmak için kullanılan ab = [(a + b)² − (a − b)²]/4 formülüne göre 23·17 çarpımı nasıl bulunur?', '(1600 − 36)/4 = 391', ['(1600 − 36)/2 = 782', '(529 − 289)/4 = 60', '(1600 + 36)/4 = 409'], 'a + b = 40 ve a − b = 6\'dır: (40² − 6²)/4 = 1564/4 = 391.'),
  ('1101₂ sayısı Horner düzeniyle onluk tabana çevrilirken soldan başlayarak her adımda 2 ile çarpılıp sonraki basamak ekleniyor. Bulunan sonuç kaçtır?', '13', ['11', '14', '26'], 'Ara değerler 1, 1·2 + 1 = 3, 3·2 + 0 = 6, 6·2 + 1 = 13\'tür. Bu, x³ + x² + 1 polinomunun x = 2\'de Horner ile hesaplanmasıdır.'),
  ('x² + 2xy + y² − 1 = 0 eşitliğini sağlayan gerçek x ve y sayıları için x + y toplamı hangi değerleri alabilir?', '−1 ya da 1', ['Yalnız 1', 'Yalnız 0', '−2 ya da 2'], 'Eşitlik (x + y)² = 1 olarak yazılır; buradan x + y = 1 ya da x + y = −1 bulunur.'),
  ('x(x + 1)(x + 2) + (x + 1) ifadesi en sade biçimde hangisine eşittir?', '(x + 1)³', ['(x + 1)²(x + 2)', 'x(x + 1)³', '(x + 1)(x² + 2)'], 'x + 1 ortak çarpanı alınırsa (x + 1)(x² + 2x + 1) = (x + 1)(x + 1)² = (x + 1)³ olur.'),
];
